-- QA3389 only; installing this schema does not pause or migrate any venue.
CREATE TABLE qa_pos_backup_runs (
 venue_id INTEGER PRIMARY KEY CHECK(venue_id=3389), account_id INTEGER NOT NULL UNIQUE CHECK(account_id=148),
 run_id TEXT NOT NULL UNIQUE, actor_id INTEGER NOT NULL,
 phase TEXT NOT NULL CHECK(phase IN ('CAPTURE','BACKED_UP','REHEARSED','COPYING','CUTOVER','COMPLETE','ABORTED')),
 paused INTEGER NOT NULL CHECK(paused IN (0,1)), backup_key TEXT, backup_hash TEXT,
 receipt_hash TEXT, revision INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL
);
CREATE TRIGGER qa_pos_pause_domain_data_insert BEFORE INSERT ON domain_data WHEN NEW.account_id=148 AND EXISTS(SELECT 1 FROM qa_pos_backup_runs WHERE paused=1) AND NOT COALESCE((NEW.store_key='bd_pos_orders_v1' AND NEW.account_id=148 AND json_valid(NEW.data_json) AND json_extract(NEW.data_json,'$.format')='bardoctor-pos-orders-v1' AND json_extract(NEW.data_json,'$.revision')=0 AND EXISTS(SELECT 1 FROM qa_pos_backup_runs r JOIN pos_order_journals j ON j.account_id=r.account_id WHERE r.paused=1 AND r.phase='CUTOVER' AND j.state='active' AND j.revision=0)),0) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;
CREATE TRIGGER qa_pos_pause_domain_data_update BEFORE UPDATE ON domain_data WHEN (OLD.account_id=148 OR NEW.account_id=148) AND EXISTS(SELECT 1 FROM qa_pos_backup_runs WHERE paused=1) AND NOT COALESCE((NEW.store_key='bd_pos_orders_v1' AND NEW.account_id=148 AND json_valid(NEW.data_json) AND json_extract(NEW.data_json,'$.format')='bardoctor-pos-orders-v1' AND json_extract(NEW.data_json,'$.revision')=0 AND EXISTS(SELECT 1 FROM qa_pos_backup_runs r JOIN pos_order_journals j ON j.account_id=r.account_id WHERE r.paused=1 AND r.phase='CUTOVER' AND j.state='active' AND j.revision=0)),0) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;
CREATE TRIGGER qa_pos_pause_domain_data_delete BEFORE DELETE ON domain_data WHEN OLD.account_id=148 AND EXISTS(SELECT 1 FROM qa_pos_backup_runs WHERE paused=1) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;
