CREATE TRIGGER qa_pos_pause_jobs_insert BEFORE INSERT ON notification_jobs WHEN NEW.venue_id=3389 AND EXISTS(SELECT 1 FROM qa_pos_backup_runs WHERE paused=1) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;
CREATE TRIGGER qa_pos_pause_jobs_update BEFORE UPDATE ON notification_jobs WHEN (OLD.venue_id=3389 OR NEW.venue_id=3389) AND EXISTS(SELECT 1 FROM qa_pos_backup_runs WHERE paused=1) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;
CREATE TRIGGER qa_pos_pause_jobs_delete BEFORE DELETE ON notification_jobs WHEN OLD.venue_id=3389 AND EXISTS(SELECT 1 FROM qa_pos_backup_runs WHERE paused=1) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;
CREATE TRIGGER qa_pos_pause_job_events_insert BEFORE INSERT ON notification_job_events WHEN EXISTS(SELECT 1 FROM notification_jobs j JOIN qa_pos_backup_runs q ON q.venue_id=j.venue_id WHERE j.id=NEW.job_id AND q.paused=1) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;
CREATE TRIGGER qa_pos_pause_deliveries_insert BEFORE INSERT ON notification_deliveries WHEN NEW.account_id=148 AND EXISTS(SELECT 1 FROM qa_pos_backup_runs WHERE paused=1) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;
