CREATE TRIGGER qa_pos_pause_deliveries_delete BEFORE DELETE ON notification_deliveries WHEN OLD.account_id=148 AND EXISTS(SELECT 1 FROM qa_pos_backup_runs WHERE paused=1) BEGIN SELECT RAISE(ABORT,'QA_POS_BACKUP_PAUSED'); END;
